'use strict';
const CREW_UI5={bind,peopleView,performanceView,interiorView,help};
TITLES.crew='Týmy baristů & personální report';
let crewSelected5=state.stores.find(s=>!s.franchise)?.id;
function crewCurrent5(){return state.stores.find(s=>s.id===crewSelected5&&!s.franchise)||state.stores.find(s=>!s.franchise);}
function crewGo5(id){crewSelected5=id;goto('crew');}
function crewView(){const stores=state.stores.filter(s=>!s.franchise),s=crewCurrent5();if(!s)return empty('Vlastní týmy se objeví po otevření kavárny. Lidi franšíz řídí partner.');crewSelected5=s.id;const c=s.crew,last=c.last,p=c.policy,owner=owner5(s),gap=crewGap5(s),summary=stores.reduce((a,s)=>{a.people+=s.crew.employees.length;a.wages+=shiftWages5(s);a.gap+=crewGap5(s);return a;},{people:0,wages:0,gap:0});return `<div class="view-toolbar"><p class="intro">Konkrétní lidé, smlouvy a dostupnost řídí skutečnou obsluhu. Report rozlišuje minulý uzavřený týden a rozpis pro další tah.</p>${field('Vybraná kavárna',`<select id="crewStore5">${stores.map(x=>option(x.id,loc(x.id).name+' · '+loc(x.id).city,s.id)).join('')}</select>`)}</div><div class="report-overview5">${metric('BARISTÉ VE FIRMĚ',summary.people,'Vlastní kavárny; franšízy řídí partner')}${metric('SMLUVNÍ MZDY / TÝDEN',money(summary.wages),'Placené i při dovolené a volné směně')}${metric('NEPOKRYTÉ SMĚNY',summary.gap,'Součet chybějících lidí za šest dnů')}${metric('ODPOVĚDNOST',esc(owner?.person.name||'Zakladatel'),loc(s.id).name)}</div><section class="card"><div class="card-head"><h2>Personální report celé sítě</h2><span class="badge">${stores.length} kaváren</span></div><div class="table-scroll"><table class="data"><thead><tr><th>Kavárna</th><th>Tým / mzdy</th><th>Příští rozpis</th><th>Poslední týden</th><th>Řízení</th></tr></thead><tbody>${stores.map(x=>`<tr><td><strong>${esc(loc(x.id).name)}</strong><small>${esc(loc(x.id).city)}</small></td><td>${x.crew.employees.length} lidí<small>${money(shiftWages5(x))} / týden</small></td><td class="${crewGap5(x)?'bad':''}">${crewGap5(x)} chybějících směn<small>${x.crew.employees.filter(p=>p.burnout>65).length} přetížených lidí</small></td><td>${x.crew.last?'T'+x.crew.last.week+' · čekání '+number(x.crew.last.wait,1)+' min':'Zatím neuzavřený'}<small>${x.crew.last?x.crew.last.gap+' chybějících směn · '+x.crew.history.at(-1).trained+' školení':'Bez vymyšlené historie'}</small></td><td><button class="soft mini" data-crew-open="${x.id}">Otevřít tým</button></td></tr>`).join('')}</tbody></table></div></section><div class="section-header"><div><span class="eyelabel">${esc(loc(s.id).city.toUpperCase())}</span><h2>${esc(loc(s.id).name)} · další týden</h2></div><button class="primary" id="crewRecruit5">Nábor baristy +</button></div><div class="live-layout"><section class="card"><div class="card-head"><h2>Jmenný rozpis · týden ${state.week}</h2><span class="badge">${c.manual?'Chráněný ruční':'Plán podle dostupnosti'}</span></div><div class="table-scroll"><table class="data crew-roster5"><thead><tr><th>Den</th>${PERIODS5.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${DAYS5.map((day,d)=>`<tr><th>${day}</th>${[0,1,2].map(k=>{const shift=crewShift5(s,d,k);return `<td><strong class="${shift.heads<s.daily.shifts[k]?'bad':''}">${shift.heads} / ${s.daily.shifts[k]} lidí</strong><small>${shift.people.map(p=>esc(p.name)).join('<br>')||'Bez obsluhy'}</small><button class="quiet mini" data-crew-cell="${d},${k}">Upravit jména</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="actions"><button class="soft" id="crewPlan5">Přepočítat jména podle dostupnosti</button><button class="soft" data-goto="interior">Počty lidí & odpovědnost</button></div><p class="sub">Jeden blok má 4 hodiny. Smlouva dovoluje 4 nebo 8 hodin za den, šest dnů týdně. Návrh přidělí pouze skutečné dostupné lidi; chybějící jména mají nulový výkon. Ruční jmenný rozpis vypne automatické počty i nábor. Přepočet jmen zachová požadované počty; automatické změny počtů povolíš v Interiéru.</p></section><section class="card"><h2>Pravidla vedení & HR</h2><p class="sub">${esc(owner?.person.name||'Zakladatel')} · ${owner?.automatic&&s.daily.auto&&s.auto.staff&&!c.manual?'Automatické zásahy mohou běžet.':'Nábor a školení čekají na povolení automatických směn a odpovědné vedení.'} Rozpočet je společný pro nábor a školení této kavárny; smluvní mzdy jsou navíc.</p><div class="fields">${field('Rozpočet zásahů / týden',input('crewBudget5',p.budget,0,100000,1000))}${field('Rezerva fixních nákladů (týdny)',input('crewReserve5',p.reserve,1,8))}${field('Cíl dovedností baristů',input('crewQuality5',p.quality,50,100))}${field('Přijatelné čekání (min)',input('crewWait5',p.wait,0,30))}</div><label class="checkbox-line"><input id="crewHire5" type="checkbox" ${p.hire?'checked':''}> Automaticky nabírat při nepokrytých směnách</label><label class="checkbox-line"><input id="crewTrain5" type="checkbox" ${p.train?'checked':''}> Školit slabé dovednosti; při dlouhé frontě rychlost</label><button class="primary wide" id="crewPolicy5">Uložit pravidla</button><p class="sub">Nábor ${money(crewFee5())}. Školení ${money(state.departments.hr?5000:8000)}: +6 bodů, nejvýše jednou na osobu za týden. Vedení školí nejvýše jednoho baristu týdně. HR zlevňuje nábor a školení a mírní přetížení. Rezerva při náboru zahrnuje i novou mzdu.</p>${last?`<div class="warning"><strong>Rozhodnutí · týden ${last.week}</strong><p>${last.decisions.map(esc).join('<br>')}</p></div>`:''}</section></div><div class="cards crew-people5">${c.employees.map(p=>`<section class="card"><div class="card-head"><h3>${esc(p.name)}</h3><span class="badge">${p.contract*4} h / den</span></div>${rows([['Smluvní mzda / týden',money(crewPay5(s,p))],...Object.entries(CREW_SKILLS5).map(([k,n])=>[n,number(p.skills[k],1)+' / 100']),['Zkušenosti / týdny v týmu',number(p.xp,1)+' / '+p.tenure],['Spokojenost / přetížení',number(p.satisfaction,0)+' / '+number(p.burnout,0)],['Dovolená',p.leave?'T'+p.leave.from+'–'+p.leave.to:'Bez plánované dovolené'],['Práce v posledním týdnu',(last?.people.find(x=>x.pid===p.pid)?.hours??'—')+' hodin']])}<div class="actions"><button class="soft mini" data-barista-edit="${p.pid}">Dostupnost & dovolená</button><button class="soft mini" data-barista-train="${p.pid}">Školení</button><button class="soft mini" data-barista-raise="${p.pid}">Mzda +10 %</button><button class="soft mini" data-barista-transfer="${p.pid}">Přesun</button><button class="soft mini" data-barista-promote="${p.pid}" ${p.xp<20||(p.skills.speed+p.skills.coffee+p.skills.service)/3<72?'disabled':''}>Povýšit na vedoucího</button><button class="quiet mini" data-barista-release="${p.pid}" ${state.over?'disabled':''}>Propustit</button></div>${p.history.length?`<p class="sub">${p.history.slice(-3).map(x=>'T'+x.week+' · '+esc(x.text)).join('<br>')}</p>`:''}</section>`).join('')}</div>${last?`<section class="card"><h2>Uzavřený týden ${last.week} · skutečná práce</h2><p class="sub">${last.gap} nepokrytých bloků · mzdy ${money(last.wages)} · čekání ${number(last.wait,1)} min. Tento záznam se změnou rozpisu nepřepíše.</p><div class="table-scroll"><table class="data"><thead><tr><th>Osoba</th><th>Odpracováno</th><th>Placená mzda</th><th>Spokojenost / přetížení</th></tr></thead><tbody>${last.people.map(p=>`<tr><td>${esc(p.name)}${p.leave?' · dovolená':''}</td><td>${p.hours} h</td><td>${money(p.wage)}</td><td>${number(p.satisfaction,0)} / ${number(p.burnout,0)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Poslední ${c.history.length} zaznamenaných týdnů: ${c.history.slice(-8).map(x=>'T'+x.week+': '+x.gap+' chybějících, '+x.trained+' školení').join(' · ')}.</p></section>`:''}`;}
function crewRecruitDialog5(){const s=crewCurrent5();show(`<h2>Nábor · ${esc(loc(s.id).name)}</h2><p>Nábor ${money(crewFee5())}. Smluvní mzda běží od dalšího tahu. Noví kandidáti přicházejí každé čtyři týdny, pokud je na trhu méně než dvanáct osob.</p>${state.baristaCandidates.map(p=>`<div class="vote"><div style="flex:1"><strong>${esc(p.name)}</strong><small>${p.contract*4} h/den · ${money(crewPay5(s,p))}/týden<br>Rychlost ${number(p.skills.speed,0)} · káva ${number(p.skills.coffee,0)} · hosté ${number(p.skills.service,0)}<br>Spokojenost ${number(p.satisfaction,0)} · přetížení ${number(p.burnout,0)}${p.leave?' · dovolená T'+p.leave.from+'–'+p.leave.to:''}</small></div><button class="soft mini" data-barista-hire="${p.pid}">Najmout</button></div>`).join('')||empty('Trh je prázdný. Další nabídky dorazí v příštím čtvrtém týdnu.')}`);on('[data-barista-hire]',b=>{if(act(()=>hireBarista5(s.id,b.dataset.baristaHire),'Barista nastoupil.')!==undefined)el('modal').close();});}
function crewCellDialog5(day,k){const s=crewCurrent5(),cell=s.crew.roster[day][k];show(`<h2>${DAYS5[day]} · ${PERIODS5[k]}</h2><p>Uložení přepne na chráněný ruční rozpis. Dodrž dostupnost i denní úvazek.</p>${s.crew.employees.map(p=>`<label class="checkbox-line"><input type="checkbox" data-roster-person="${p.pid}" ${cell.includes(p.pid)?'checked':''} ${!crewAvailable5(p,day,k)?'disabled':''}> ${esc(p.name)} · ${p.contract*4} h / den ${!crewAvailable5(p,day,k)?'· nedostupný':''}</label>`).join('')}<button class="primary wide" id="crewCellSave5">Uložit tuto směnu</button>`);el('crewCellSave5').onclick=()=>{try{const roster=JSON.parse(JSON.stringify(s.crew.roster));roster[day][k]=[...document.querySelectorAll('[data-roster-person]:checked:not(:disabled)')].map(x=>x.dataset.rosterPerson);setCrewRoster5(s.id,roster);persist();render();el('modal').close();}catch(e){toast(e.message)}};}
function baristaEditDialog5(pid){const s=crewCurrent5(),p=s.crew.employees.find(p=>p.pid===pid);show(`<h2>${esc(p.name)} · dostupnost</h2><p>Smluvní mzda pokračuje i v týdnech bez práce. Změna dostupnosti může nechat ruční směnu bez náhrady.</p><div class="fields"><div>${DAYS5.map((day,i)=>`<label class="checkbox-line"><input data-barista-day="${i}" type="checkbox" ${p.days[i]?'checked':''}> ${day}</label>`).join('')}</div><div>${PERIODS5.map((period,i)=>`<label class="checkbox-line"><input data-barista-period="${i}" type="checkbox" ${p.periods[i]?'checked':''}> ${period}</label>`).join('')}</div></div><button class="primary wide" id="baristaAvailability5">Uložit dostupnost</button><h3>Dovolená</h3><div class="fields">${field('Začátek · týden',input('baristaLeaveFrom5',state.week,state.week,state.week+26))}${field('Délka · týdny',input('baristaLeaveWeeks5',1,1,8))}</div><button class="soft" id="baristaLeave5">Schválit placenou dovolenou</button>${p.leave?'<button class="quiet" id="baristaLeaveCancel5">Zrušit plán dovolené</button>':''}`);const finish=fn=>{try{fn();persist();render();el('modal').close();}catch(e){toast(e.message)}};el('baristaAvailability5').onclick=()=>finish(()=>availabilityBarista5(s.id,pid,[...document.querySelectorAll('[data-barista-day]')].map(x=>x.checked),[...document.querySelectorAll('[data-barista-period]')].map(x=>x.checked)));el('baristaLeave5').onclick=()=>finish(()=>leaveBarista5(s.id,pid,Number(el('baristaLeaveFrom5').value),Number(el('baristaLeaveWeeks5').value)));if(el('baristaLeaveCancel5'))el('baristaLeaveCancel5').onclick=()=>finish(()=>{guard();p.leave=null;planCrew5(s)});}
function baristaTrainDialog5(pid){const s=crewCurrent5(),p=s.crew.employees.find(p=>p.pid===pid);show(`<h2>Školení · ${esc(p.name)}</h2><p>+6 bodů, cena ${money(state.departments.hr?5000:8000)}. Jedno školení na osobu za týden; dovednosti a zkušenosti zůstávají při přesunu i povýšení.</p>${Object.entries(CREW_SKILLS5).map(([k,n])=>`<button class="soft wide" data-barista-skill="${k}" ${p.trained===state.week||p.skills[k]>=100?'disabled':''}>${n} · ${number(p.skills[k],1)} / 100</button>`).join('')}`);on('[data-barista-skill]',b=>{if(act(()=>trainBarista5(s.id,pid,b.dataset.baristaSkill),'Školení dokončeno.')!==undefined)el('modal').close();});}
function baristaReleaseDialog19(id,pid){try{const q=releaseBaristaQuote19(id,pid);confirmAction('Propustit baristu?',esc(q.name)+' · '+esc(loc(id).name)+'. Smlouva skončí ihned, barista opustí tým i budoucí směny. Minulé výsledky zůstanou zachované.',()=>{try{releaseBarista5(id,pid,q);}catch(e){const warning=el('baristaReleaseError19');warning.hidden=false;warning.textContent=e.message;el('confirmAction').disabled=true;throw e;}},'Propustit a zaplatit odstupné');const detail=document.createElement('div');detail.id='baristaReleaseDetails19';detail.innerHTML='<p id="baristaReleaseError19" class="warning" role="alert" hidden></p>'+rows([['Odstupné · jedna týdenní mzda',money(q.cost)],['Mzdy týmu / další týden',money(q.wages)+' → '+money(q.nextWages)],['Nepokryté směny · 6 dnů',q.gap+' → '+q.nextGap],['V týmu zůstane',q.remaining+' '+(q.remaining===1?'barista':q.remaining>=2&&q.remaining<=4?'baristé':'baristů')],['Hotovost po propuštění',money(q.cash-q.cost)]])+(q.cash<q.cost?'<p class="warning">Na odstupné chybí '+money(q.cost-q.cash)+'. Propuštění se neprovede.</p>':q.remaining===0?'<p class="warning">Tým zůstane prázdný. Bez skutečných lidí nebude kavárna obsluhovat hosty.</p>':'')+(q.autoHire?'<p class="sub">Automatický nábor je povolený. Vedení může v dalších týdnech doplnit tým; pravidlo změníš v Lidé → Pravidla a výsledky.</p>':'');el('modalContent').querySelector('.actions').before(detail);el('confirmAction').disabled=q.cash<q.cost;el('cancelAction').textContent='Zpět bez propuštění';}catch(e){toast(e.message);}}
function baristaTransferDialog5(pid){const s=crewCurrent5(),targets=state.stores.filter(x=>!x.franchise&&x.id!==s.id&&loc(x.id).city===loc(s.id).city);show(`<h2>Přesun mezi týmy</h2><p>Přesun zachová osobu a smlouvu, mzda se odvozuje od základu cílové kavárny. Původní tým může zůstat neobsazený.</p>${targets.map(x=>`<button class="soft wide" data-barista-destination="${x.id}">${esc(loc(x.id).name)}</button>`).join('')||empty('Nejprve otevři další vlastní kavárnu ve stejném městě.')}`);on('[data-barista-destination]',b=>{try{transferBarista5(s.id,pid,b.dataset.baristaDestination);persist();render();el('modal').close();}catch(e){toast(e.message)}});}
peopleView=function(){return `<div class="actions"><button class="primary" data-goto="crew">Otevřít týmy baristů & HR report</button></div>`+CREW_UI5.peopleView();};
performanceView=function(){return `<div class="actions"><button class="soft" data-goto="crew">Personální report · baristé, směny & školení</button></div>`+CREW_UI5.performanceView();};
interiorView=function(){return `<div class="actions"><button class="soft" data-crew-open="${currentDesign5().id}">Jmenné týmy, smlouvy & dovolené</button></div>`+CREW_UI5.interiorView().replace('Stejný součet směn má stejnou cenu.','Mzdy určuje součet smluv skutečných lidí; neobsazené směny smlouvu nezruší.');};
bind=function(){CREW_UI5.bind();on('[data-crew-open]',b=>crewGo5(b.dataset.crewOpen));if(el('crewStore5'))el('crewStore5').onchange=()=>{crewSelected5=el('crewStore5').value;render()};if(el('crewRecruit5'))el('crewRecruit5').onclick=crewRecruitDialog5;if(el('crewPlan5'))el('crewPlan5').onclick=()=>act(()=>automaticRoster5(crewCurrent5().id),'Jména přepočítána; počty lidí zůstávají.');on('[data-crew-cell]',b=>{const [d,k]=b.dataset.crewCell.split(',').map(Number);crewCellDialog5(d,k)});if(el('crewPolicy5'))el('crewPolicy5').onclick=()=>act(()=>setCrewPolicy5(crewCurrent5().id,{hire:el('crewHire5').checked,train:el('crewTrain5').checked,budget:Number(el('crewBudget5').value),reserve:Number(el('crewReserve5').value),quality:Number(el('crewQuality5').value),wait:Number(el('crewWait5').value)}),'Pravidla týmu uložena.');on('[data-barista-edit]',b=>baristaEditDialog5(b.dataset.baristaEdit));on('[data-barista-train]',b=>baristaTrainDialog5(b.dataset.baristaTrain));on('[data-barista-transfer]',b=>baristaTransferDialog5(b.dataset.baristaTransfer));on('[data-barista-raise]',b=>act(()=>raiseBarista5(crewCurrent5().id,b.dataset.baristaRaise),'Smluvní mzda zvýšena.'));on('[data-barista-promote]',b=>confirmAction('Povýšit baristu?','Povýšení stojí 12 000 Kč, osoba opustí směny a převezme vedení této kavárny. Dosavadní vedoucí se vrátí na trh práce.',()=>promoteBarista5(crewCurrent5().id,b.dataset.baristaPromote),'Povýšit'));on('[data-barista-release]',b=>baristaReleaseDialog19(crewCurrent5().id,b.dataset.baristaRelease));};
help=function(){CREW_UI5.help();const p=document.createElement('p');p.textContent='Týmy & HR report: baristé mají jméno, dovednosti, úvazek a dostupnost. Dovolená snižuje kapacitu, smluvní mzda pokračuje. Počty směn jsou cílem; obsluhují jen přidělení skuteční lidé. Nastav pravidla náboru a školení s rozpočtem a rezervou a povol směny odpovědnému vedení v Interiéru. Ruční jmenný rozpis se sám nepřepíše. Baristu lze školit, přesunout v rámci města nebo povýšit na vedoucího.';el('modalContent').append(p);};el('help').onclick=help;
render();
